(1250, 'library', '/ˈlaɪbrɛri/', 'noun', '{"zh-TW":["圖書館"],"en":["a building or room with books for reading or borrowing"]}', NULL, 'public library / digital library', '[{"en":"The company has a digital library for employees.","zh-TW":"公司為員工設有數位圖書館。"},{"en":"I researched at the public library.","zh-TW":"我在公共圖書館做了研究。"}]', '{"noun":"library","noun2":"librarian"}', NULL, 3, 1250),
(1251, 'license', '/ˈlaɪsns/', 'noun, verb', '{"zh-TW":["執照；許可證","授權；許可"],"en":["official permission to do something","to grant a license"]}', NULL, 'driver''s license / license agreement / software license', '[{"en":"You need a license to operate this machinery.","zh-TW":"你需要執照才能操作這台機器。"},{"en":"The software is licensed for commercial use.","zh-TW":"該軟體已獲授權供商業使用。"}]', '{"noun":"license, licensee","verb":"license","adjective":"licensed"}', NULL, 3, 1251),
(1252, 'life', '/laɪf/', 'noun', '{"zh-TW":["生命；生活"],"en":["the existence of a person","the way someone lives"]}', NULL, 'work-life balance / shelf life', '[{"en":"Work-life balance is important to us.","zh-TW":"工作與生活的平衡對我們很重要。"},{"en":"The product has a shelf life of two years.","zh-TW":"產品的保質期為兩年。"}]', '{"noun":"life","adjective":"lifelong","noun2":"lifestyle","noun3":"lifetime"}', NULL, 1, 1252),
(1253, 'light', '/laɪt/', 'noun', '{"zh-TW":["光；燈；輕的"],"en":["brightness","not heavy"]}', NULL, 'in light of / highlight', '[{"en":"In light of recent events, we changed plans.","zh-TW":"鑑於最近的事件，我們改變了計畫。"},{"en":"This laptop is very light and portable.","zh-TW":"這台筆電很輕便攜帶。"}]', '{"noun":"light","adjective":"light","verb":"light","noun2":"lighting","verb2":"lighten"}', NULL, 2, 1253),
(1254, 'lightning', '/ˈlaɪtnɪŋ/', 'noun', '{"zh-TW":["閃電"],"en":["a flash of bright light in the sky during a storm"]}', '{"root":{"text":"light","meaning":"light (光)"},"suffix":{"text":"-ning","meaning":"action (動作)"},"logic":"天空中光的動作，即「閃電」。"}', 'lightning bolt / lightning strike / lightning rod', '[{"en":"Lightning struck the old tree in the park.","zh-TW":"閃電擊中了公園裡的老樹。"},{"en":"Never stand under a tree during a lightning storm.","zh-TW":"閃電暴風雨時千萬不要站在樹下。"}]', NULL, NULL, 3, 1254),
(1255, 'likewise', '/ˈlaɪkwaɪz/', 'adverb', '{"zh-TW":["同樣地；也"],"en":["in the same way; also"]}', NULL, 'do likewise / likewise, ...', '[{"en":"The first team finished early, and the second did likewise.","zh-TW":"第一組提前完成了，第二組也是如此。"},{"en":"Likewise, we must consider the long-term effects.","zh-TW":"同樣地，我們必須考慮長期影響。"}]', '{"adverb":"likewise"}', NULL, 3, 1255),
(1256, 'limit', '/ˈlɪmɪt/', 'noun, verb', '{"zh-TW":["限制；限度"],"en":["a boundary or restriction"]}', NULL, 'set/impose a limit / speed limit / within limits', '[{"en":"There is a limit to what we can achieve in one day.","zh-TW":"我們一天能完成的事情有限。"},{"en":"The government imposed limits on imports.","zh-TW":"政府對進口實施了限制。"}]', '{"noun":"limit, limitation","verb":"limit","adjective":"limited, limitless"}', NULL, 2, 1256),
(1257, 'line', '/laɪn/', 'noun', '{"zh-TW":["線；排；產品線"],"en":["a long narrow mark; a row of people; a range of products"]}', NULL, 'product line / bottom line / assembly line', '[{"en":"The company expanded its product line.","zh-TW":"公司擴大了其產品線。"},{"en":"The bottom line is that we need more revenue.","zh-TW":"重點是我們需要更多收入。"}]', '{"noun":"line","verb":"line","adjective":"linear"}', NULL, 1, 1257),
(1258, 'link', '/lɪŋk/', 'noun, verb', '{"zh-TW":["連結；聯繫"],"en":["a connection between things"]}', NULL, 'link between / link to / a direct link', '[{"en":"There is a clear link between education and income.","zh-TW":"教育和收入之間有明確的關聯。"},{"en":"Please click the link below for more details.","zh-TW":"請點擊下面的連結以獲取更多詳情。"}]', '{"noun":"link, linkage","verb":"link"}', NULL, 1, 1258),
(1259, 'liquid', '/ˈlɪkwɪd/', 'noun, adjective', '{"zh-TW":["液體","液態的；流動的"],"en":["a substance that flows freely","in the form of a liquid; easily converted to cash"]}', NULL, 'liquid assets / liquid state', '[{"en":"The company needs more liquid assets.","zh-TW":"公司需要更多的流動資產。"},{"en":"Water is a liquid at room temperature.","zh-TW":"水在室溫下是液體。"}]', '{"noun":"liquid, liquidity","adjective":"liquid","verb":"liquidate"}', NULL, 2, 1259),
(1260, 'list', '/lɪst/', 'noun, verb', '{"zh-TW":["清單；列表","列出"],"en":["a series of items written together","to write items in a list"]}', NULL, 'waiting list / mailing list / list requirements', '[{"en":"Please add this task to the priority list.","zh-TW":"請將此任務添加到優先清單中。"},{"en":"The report lists all the recommendations.","zh-TW":"報告列出了所有建議。"}]', '{"noun":"list, listing","verb":"list"}', NULL, 1, 1260),
(1261, 'listen', '/ˈlɪsən/', 'verb', '{"zh-TW":["聽；傾聽"],"en":["to pay attention to sounds"]}', NULL, 'listen carefully / listen to', '[{"en":"Please listen carefully to the instructions.","zh-TW":"請仔細聽說明。"},{"en":"A good manager listens to feedback.","zh-TW":"好的經理會聽取回饋。"}]', '{"verb":"listen","noun":"listener","noun2":"listening"}', NULL, 2, 1261),
(1262, 'literacy', '/ˈlɪtərəsi/', 'noun', '{"zh-TW":["識字能力；素養"],"en":["the ability to read and write; competence in a subject"]}', NULL, 'financial/digital/computer literacy', '[{"en":"Digital literacy is an essential skill in the modern workplace.","zh-TW":"數位素養是現代職場的必備技能。"},{"en":"The program aims to improve adult literacy rates.","zh-TW":"該計劃旨在提高成人識字率。"}]', '{"noun":"literacy","adjective":"literate, illiterate"}', NULL, 3, 1262),
(1263, 'litigation', '/ˌlɪtɪˈɡeɪʃən/', 'noun', '{"zh-TW":["訴訟","訴訟；起訴"],"en":["the process of taking legal action"]}', NULL, 'avoid litigation / pending litigation', '[{"en":"We want to avoid costly litigation.","zh-TW":"我們想避免昂貴的訴訟。"},{"en":"There is pending litigation against the company.","zh-TW":"有未決訴訟針對公司。"},{"en":"The company settled to avoid costly litigation.","zh-TW":"公司為避免昂貴的訴訟而達成了和解。"},{"en":"There is pending litigation against the manufacturer.","zh-TW":"有針對製造商的未決訴訟。"}]', '{"noun":"litigation","verb":"litigate","noun2":"litigant"}', NULL, 4, 1263),
(1264, 'little', '/ˈlɪtəl/', 'adjective', '{"zh-TW":["小的；少的"],"en":["small in size","not much"]}', NULL, 'a little / little by little', '[{"en":"We have a little time left.","zh-TW":"我們還有一點時間。"},{"en":"Little by little, sales improved.","zh-TW":"銷售逐漸改善了。"}]', '{"adjective":"little","adverb":"little"}', NULL, 2, 1264),
(1265, 'live', '/lɪv/', 'verb', '{"zh-TW":["居住；生活；現場的"],"en":["to have one''s home","broadcast in real time"]}', NULL, 'live broadcast / live up to', '[{"en":"The event will be a live broadcast.","zh-TW":"活動將會現場直播。"},{"en":"The product must live up to expectations.","zh-TW":"產品必須達到預期。"}]', '{"verb":"live","adjective":"live","adjective2":"lively","noun":"living","noun2":"livelihood"}', NULL, 1, 1265),
(1266, 'load', '/loʊd/', 'noun, verb', '{"zh-TW":["負荷；載重量","裝載"],"en":["the amount carried; a burden","to put goods onto a vehicle"]}', NULL, 'heavy load / workload / load cargo', '[{"en":"The truck was carrying a heavy load.","zh-TW":"卡車載著沉重的貨物。"},{"en":"Workers loaded the containers onto the ship.","zh-TW":"工人們把貨櫃裝上船。"}]', '{"noun":"load","verb":"load, unload"}', NULL, 1, 1266),
(1267, 'loan', '/loʊn/', 'noun, verb', '{"zh-TW":["貸款；借款"],"en":["money lent at interest"]}', NULL, 'bank loan / take out a loan / loan application', '[{"en":"She took out a loan to start her business.","zh-TW":"她貸款來創業。"},{"en":"The bank approved our loan application.","zh-TW":"銀行批准了我們的貸款申請。"}]', '{"noun":"loan","verb":"loan"}', NULL, 1, 1267),
(1268, 'lobby', '/ˈlɒbi/', 'verb', '{"zh-TW":["遊說","大廳；遊說"],"en":["to try to influence politicians","an entrance hall; a group trying to influence policy"]}', NULL, 'lobby for / lobbying group; hotel lobby / lobby for/against', '[{"en":"They lobbied for stricter gun laws.","zh-TW":"他們遊說推動更嚴格的槍枝法。"},{"en":"The industry lobby is very powerful.","zh-TW":"產業遊說團體非常有力。"},{"en":"Please wait in the hotel lobby.","zh-TW":"請在酒店大廳等候。"},{"en":"Industry groups lobbied against the new regulation.","zh-TW":"行業團體遊說反對新法規。"}]', '{"noun":"lobby","noun2":"lobbyist","verb":"lobby"}', NULL, 2, 1268),
(1269, 'local', '/ˈloʊkl/', 'adjective, noun', '{"zh-TW":["當地的；本地的","當地居民"],"en":["relating to a particular place","a person living in a particular area"]}', NULL, 'local government/community/business', '[{"en":"We source ingredients from local suppliers.","zh-TW":"我們從當地供應商採購原料。"},{"en":"The festival is supported by the local community.","zh-TW":"這個節日得到當地社區的支持。"}]', '{"noun":"local, locality","adjective":"local","adverb":"locally","verb":"localize"}', NULL, 2, 1269),
(1270, 'locate', '/ˈloʊkeɪt/', 'verb', '{"zh-TW":["定位；找到；設在"],"en":["to find the position of; to establish in a place"]}', NULL, 'locate a file/office / be located in', '[{"en":"Our headquarters is located in downtown Tokyo.","zh-TW":"我們的總部位於東京市中心。"},{"en":"Can you help me locate the missing file?","zh-TW":"你能幫我找到那個遺失的檔案嗎？"}]', '{"noun":"location","verb":"locate","adjective":"located"}', NULL, 2, 1270),
(1271, 'log', '/lɔːɡ/', 'noun, verb', '{"zh-TW":["記錄；日誌","記錄；登錄"],"en":["an official record of events","to make a record of"]}', NULL, 'log in / activity log / log data', '[{"en":"Please log all incoming calls.","zh-TW":"請記錄所有來電。"},{"en":"The system logs every transaction automatically.","zh-TW":"系統自動記錄每筆交易。"}]', '{"noun":"log","verb":"log"}', NULL, 1, 1271),
