(1275, 'long-term', '/ˌlɔːŋˈtɜːrm/', 'adjective', '{"zh-TW":["長期的"],"en":["lasting for a long time"]}', NULL, 'long-term plan/goal/investment/strategy', '[{"en":"We need a long-term strategy for growth.","zh-TW":"我們需要一個長期的成長策略。"},{"en":"Long-term investments tend to yield higher returns.","zh-TW":"長期投資往往能帶來更高的回報。"}]', '{"adjective":"long-term"}', NULL, 3, 1275),
