(1277, 'lose', '/luːz/', 'verb', '{"zh-TW":["失去；輸"],"en":["to no longer have","to fail to win"]}', NULL, 'lose money / lose track', '[{"en":"We cannot afford to lose this client.","zh-TW":"我們不能失去這個客戶。"},{"en":"Don''t lose track of expenses.","zh-TW":"不要忽略了開支。"}]', '{"verb":"lose","noun":"loss","noun2":"loser","adjective":"lost"}', NULL, 1, 1277),
