(1279, 'loud', '/laʊd/', 'adjective', '{"zh-TW":["大聲的"],"en":["producing much noise"]}', NULL, 'loud and clear / think out loud', '[{"en":"The message came through loud and clear.","zh-TW":"訊息傳達得非常清楚。"},{"en":"Let me think out loud for a moment.","zh-TW":"讓我大聲想一下。"}]', '{"adjective":"loud","adverb":"loudly","noun":"loudness"}', NULL, 1, 1279),
