(1281, 'love', '/lʌv/', 'verb', '{"zh-TW":["愛；喜愛"],"en":["to have strong affection for","to like very much"]}', NULL, 'love to / labor of love', '[{"en":"Customers love our new product.","zh-TW":"客戶很喜歡我們的新產品。"},{"en":"Building this app was a labor of love.","zh-TW":"開發這個應用程式是出於熱愛。"}]', '{"verb":"love","noun":"love","adjective":"lovely","adjective2":"lovable"}', NULL, 1, 1281),
(1282, 'low', '/loʊ/', 'adjective', '{"zh-TW":["低的"],"en":["below the usual level","not high"]}', NULL, 'low cost / low risk', '[{"en":"We offer low-cost solutions.","zh-TW":"我們提供低成本方案。"},{"en":"This is a low-risk investment.","zh-TW":"這是低風險投資。"}]', '{"adjective":"low","verb":"lower","noun":"low","adverb":"low"}', NULL, 1, 1282),
