(1284, 'luck', '/lʌk/', 'noun', '{"zh-TW":["運氣"],"en":["good or bad things that happen by chance"]}', NULL, 'good luck / out of luck', '[{"en":"Good luck with your presentation!","zh-TW":"祝你簡報順利！"},{"en":"We are out of luck with this supplier.","zh-TW":"我們跟這個供應商運氣不好。"}]', '{"noun":"luck","adjective":"lucky","adverb":"luckily","adjective2":"unlucky"}', NULL, 1, 1284),
(1285, 'lucrative', '/ˈluːkrətɪv/', 'adjective', '{"zh-TW":["有利可圖的；賺錢的"],"en":["producing a large amount of profit"]}', NULL, 'lucrative business/deal/market/contract', '[{"en":"The overseas market proved highly lucrative.","zh-TW":"海外市場被證明是非常有利可圖的。"},{"en":"She landed a lucrative consulting contract.","zh-TW":"她獲得了一份利潤豐厚的顧問合同。"}]', '{"adjective":"lucrative"}', NULL, 3, 1285),
(1286, 'luggage', '/ˈlʌɡɪdʒ/', 'noun', '{"zh-TW":["行李"],"en":["suitcases or bags used when traveling"]}', NULL, 'carry-on luggage / check luggage / luggage allowance', '[{"en":"Please keep your luggage with you at all times.","zh-TW":"請隨時注意您的行李。"},{"en":"The airline lost my luggage.","zh-TW":"航空公司弄丟了我的行李。"}]', '{"noun":"luggage"}', NULL, 3, 1286),
(1287, 'lump', '/lʌmp/', 'noun, adjective', '{"zh-TW":["一次性的；塊"],"en":["a compact mass; paid in one amount"]}', NULL, 'lump sum / lump together', '[{"en":"He received a lump sum payment upon retirement.","zh-TW":"他退休時收到了一次性付款。"},{"en":"Don''t lump all the expenses together.","zh-TW":"不要把所有費用混在一起。"}]', '{"noun":"lump","verb":"lump","adjective":"lump-sum"}', NULL, 1, 1287),
