(1289, 'machine', '/məˈʃiːn/', 'noun', '{"zh-TW":["機器"],"en":["a device that performs a task"]}', NULL, 'machine learning / vending machine', '[{"en":"Machine learning is transforming business.","zh-TW":"機器學習正在改變商業。"},{"en":"The vending machine is in the lobby.","zh-TW":"自動販賣機在大廳。"}]', '{"noun":"machine","noun2":"machinery","noun3":"machinist"}', NULL, 3, 1289),
(1290, 'machinery', '/məˈʃiːnəri/', 'noun', '{"zh-TW":["機械；機器設備"],"en":["machines collectively; the components of a machine"]}', NULL, 'heavy/industrial machinery', '[{"en":"The factory invested in new machinery.","zh-TW":"工廠投資了新機器設備。"},{"en":"Heavy machinery is used in construction.","zh-TW":"重型機械用於建築工程。"}]', '{"noun":"machinery, machine","verb":"machine"}', NULL, 3, 1290),
(1291, 'magnitude', '/ˈmæɡnɪtuːd/', 'noun', '{"zh-TW":["規模；重要性"],"en":["the great size or importance of something"]}', NULL, 'of this/such magnitude / order of magnitude', '[{"en":"We have never faced a crisis of this magnitude.","zh-TW":"我們從未面臨過如此規模的危機。"},{"en":"The magnitude of the problem was underestimated.","zh-TW":"問題的嚴重性被低估了。"}]', '{"noun":"magnitude"}', NULL, 3, 1291),
(1292, 'mainstream', '/ˈmeɪnstriːm/', 'noun, adjective', '{"zh-TW":["主流"],"en":["the ideas or activities shared by most people"]}', NULL, 'mainstream media/culture/market', '[{"en":"Electric vehicles are entering the mainstream market.","zh-TW":"電動車正在進入主流市場。"},{"en":"The idea has now become mainstream.","zh-TW":"這個想法現在已成為主流。"}]', '{"noun":"mainstream","adjective":"mainstream","verb":"mainstream"}', NULL, 4, 1292),
(1293, 'maintain', '/meɪnˈteɪn/', 'verb', '{"zh-TW":["維持；保養","維持；保持；維修"],"en":["to keep in a particular state","to assert as true","to keep in good condition; to continue at the same level"]}', '{"root":{"text":"main","meaning":"hand (手)"},"suffix":{"text":"tain","meaning":"hold (持有)"},"logic":"用手持住不放，即「維持」。"}', 'maintain quality / maintain a relationship; maintain standards/quality/equipment', '[{"en":"It''s important to maintain a healthy lifestyle.","zh-TW":"維持健康的生活方式很重要。"},{"en":"The building is well maintained.","zh-TW":"這棟建築保養得很好。"},{"en":"It is important to maintain high standards of quality.","zh-TW":"保持高品質標準很重要。"},{"en":"The building is well maintained.","zh-TW":"這棟建築維護得很好。"}]', '{"noun":"maintenance","verb":"maintain"}', NULL, 3, 1293),
(1294, 'major', '/ˈmeɪdʒər/', 'noun', '{"zh-TW":["主修科目","主要的；重大的"],"en":["the main subject a student studies","very important or large","a university subject of specialization"]}', NULL, 'major in / change one''s major; major factor/issue/change / major in', '[{"en":"What''s your major?","zh-TW":"你的主修是什麼？"},{"en":"She majored in psychology.","zh-TW":"她主修心理學。"},{"en":"Cost reduction is a major priority this year.","zh-TW":"降低成本是今年的主要優先事項。"},{"en":"She majored in business administration.","zh-TW":"她主修企業管理。"}]', '{"adjective":"major","noun2":"majority","noun":"major, majority","verb":"major"}', NULL, 2, 1294),
(1295, 'majority', '/məˈdʒɔːrəti/', 'noun', '{"zh-TW":["多數；大多數"],"en":["the greater number or part"]}', NULL, 'the vast majority / majority vote / majority of', '[{"en":"The vast majority of employees support the change.","zh-TW":"絕大多數員工支持這項變革。"},{"en":"The proposal passed by a majority vote.","zh-TW":"該提案以多數票通過。"}]', '{"noun":"majority, major","adjective":"major"}', NULL, 3, 1295),
