(1297, 'male', '/meɪl/', 'adjective', '{"zh-TW":["男性的"],"en":["relating to men or boys"]}', NULL, 'male employee / male-dominated', '[{"en":"The industry is still male-dominated.","zh-TW":"這個產業仍由男性主導。"},{"en":"Both male and female candidates are welcome.","zh-TW":"歡迎男性和女性候選人。"}]', '{"adjective":"male","noun":"male"}', NULL, 1, 1297),
(1298, 'malfunction', '/mælˈfʌŋkʃn/', 'noun, verb', '{"zh-TW":["故障；失靈"],"en":["a failure to work correctly"]}', NULL, 'equipment/system malfunction', '[{"en":"A malfunction in the system caused the delay.","zh-TW":"系統故障導致了延誤。"},{"en":"The machine malfunctioned during production.","zh-TW":"機器在生產過程中出了故障。"}]', '{"noun":"malfunction","verb":"malfunction"}', NULL, 4, 1298),
