(1339, 'membership', '/ˈmembərʃɪp/', 'noun', '{"zh-TW":["會員資格；會員人數"],"en":["the state of being a member; the total number of members"]}', NULL, 'membership fee / apply for membership', '[{"en":"Membership is open to all employees.","zh-TW":"所有員工都可以申請會員資格。"},{"en":"The club''s membership has grown to 500.","zh-TW":"俱樂部的會員人數已增至500人。"}]', '{"noun":"membership, member"}', NULL, 4, 1339),
(1340, 'memo', '/ˈmemoʊ/', 'noun', '{"zh-TW":["備忘錄"],"en":["a short written message used in business"]}', NULL, 'send/write a memo / internal memo', '[{"en":"The manager sent a memo to all staff.","zh-TW":"經理向全體員工發送了一份備忘錄。"},{"en":"Please refer to the attached memo for details.","zh-TW":"詳情請參閱附件備忘錄。"}]', '{"noun":"memo, memorandum"}', NULL, 1, 1340),
(1341, 'mentor', '/ˈmɛntɔːr/', 'noun', '{"zh-TW":["導師；良師益友","導師；顧問","指導"],"en":["an experienced person who advises","to guide and advise"]}', NULL, 'find a mentor / mentor program; mentor program / find a mentor / mentor someone', '[{"en":"She became my mentor at work.","zh-TW":"她成為了我工作中的導師。"},{"en":"Every student is assigned a mentor.","zh-TW":"每位學生都被分配了一位導師。"},{"en":"Every new employee is assigned a mentor.","zh-TW":"每位新員工都會被分配一位導師。"},{"en":"She mentored several junior colleagues.","zh-TW":"她指導了幾位初級同事。"}]', '{"verb":"mentor","noun2":"mentorship","noun":"mentor, mentorship, mentoring"}', NULL, 2, 1341),
(1342, 'merchandise', '/ˈmɜːrtʃəndaɪz/', 'noun', '{"zh-TW":["商品；貨物","推銷"],"en":["goods that are bought and sold","goods for sale","to promote the sale of goods"]}', '{"root":{"text":"merch","meaning":"trade (貿易)"},"suffix":{"text":"-andise","meaning":"collective (集合)"},"logic":"貿易的集合，即「商品」。"}', 'merchandise display / branded merchandise', '[{"en":"The store sells a wide range of merchandise.","zh-TW":"這家店販售各種商品。"},{"en":"All merchandise must be paid for before leaving.","zh-TW":"所有商品在離開前必須付款。"},{"en":"The store offers a wide range of merchandise.","zh-TW":"這家商店提供各種各樣的商品。"},{"en":"The products were merchandised effectively.","zh-TW":"產品被有效地推銷。"}]', '{"noun":"merchant","verb":"merchandise"}', NULL, 4, 1342),
(1343, 'merge', '/mɜːrdʒ/', 'verb', '{"zh-TW":["合併；融合"],"en":["to combine or join together"]}', NULL, 'merge with / merge into / merge companies', '[{"en":"The two companies merged to form a larger corporation.","zh-TW":"兩家公司合併成為一家更大的企業。"},{"en":"The lanes merge ahead.","zh-TW":"前方車道合併。"}]', '{"noun":"merger","verb":"merge"}', NULL, 2, 1343),
(1344, 'merit', '/ˈmerɪt/', 'noun, verb', '{"zh-TW":["優點；功績","值得"],"en":["a good quality or feature","to deserve or be worthy of"]}', NULL, 'on merit / merit attention/consideration', '[{"en":"Each proposal will be judged on its own merit.","zh-TW":"每個提案將根據其本身的優點進行評判。"},{"en":"The idea merits further investigation.","zh-TW":"這個想法值得進一步研究。"}]', '{"noun":"merit","verb":"merit","adjective":"meritorious"}', NULL, 2, 1344),
(1345, 'method', '/ˈmeθəd/', 'noun', '{"zh-TW":["方法；辦法"],"en":["a way of doing something systematically"]}', NULL, 'teaching/payment method / method of', '[{"en":"We need to find a more efficient method.","zh-TW":"我們需要找到一種更有效率的方法。"},{"en":"What payment methods do you accept?","zh-TW":"你們接受哪些付款方式？"}]', '{"noun":"method, methodology","adjective":"methodical","adverb":"methodically"}', NULL, 2, 1345),
(1346, 'methodology', '/ˌmɛθəˈdɒlədʒi/', 'noun', '{"zh-TW":["方法論"],"en":["a system of methods used in a particular area"]}', NULL, 'research methodology / agile methodology', '[{"en":"We follow agile methodology in development.","zh-TW":"我們在開發中遵循敏捷方法論。"},{"en":"The research methodology is clearly defined.","zh-TW":"研究方法論有明確的定義。"},{"en":"The company adopted an agile methodology for software development.","zh-TW":"公司採用了敏捷方法論進行軟體開發。"},{"en":"Please describe the methodology used in your study.","zh-TW":"請描述你研究中使用的方法論。"}]', '{"noun":"methodology","adjective":"methodological","adverb":"methodologically"}', NULL, 4, 1346),
(1347, 'meticulous', '/mɪˈtɪkjələs/', 'adjective', '{"zh-TW":["一絲不苟的；極其仔細的"],"en":["showing great attention to detail"]}', NULL, 'meticulous attention to detail / meticulous planning', '[{"en":"She is meticulous in her work and rarely makes errors.","zh-TW":"她工作一絲不苟，很少犯錯。"},{"en":"Meticulous planning ensured the event''s success.","zh-TW":"細緻的規劃確保了活動的成功。"}]', '{"adjective":"meticulous","adverb":"meticulously"}', NULL, 4, 1347),
(1348, 'middle', '/ˈmɪdəl/', 'noun', '{"zh-TW":["中間；中部"],"en":["the central point or position"]}', NULL, 'middle management / in the middle of', '[{"en":"She is in middle management.","zh-TW":"她是中層管理人員。"},{"en":"We are in the middle of negotiations.","zh-TW":"我們正在談判中。"}]', '{"noun":"middle","adjective":"middle"}', NULL, 2, 1348),
(1349, 'midterm', '/ˈmɪdtɜːrm/', 'noun', '{"zh-TW":["期中考"],"en":["an exam in the middle of a term"]}', NULL, 'midterm exam / midterm grades', '[{"en":"I''m studying for my midterms.","zh-TW":"我正在準備期中考。"},{"en":"Midterm grades will be posted Friday.","zh-TW":"期中成績將在週五公布。"}]', NULL, NULL, 3, 1349);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(1350, 'migrate', '/ˈmaɪɡreɪt/', 'verb', '{"zh-TW":["遷移；移民"],"en":["to move from one place to another"]}', NULL, 'migrate to / migrate data/systems', '[{"en":"Many companies are migrating their data to the cloud.","zh-TW":"許多公司正在將數據遷移到雲端。"},{"en":"Birds migrate south for the winter.","zh-TW":"鳥類冬天遷徙到南方。"}]', '{"noun":"migration, migrant","verb":"migrate","adjective":"migratory"}', NULL, 3, 1350),
(1351, 'milestone', '/ˈmaɪlstoʊn/', 'noun', '{"zh-TW":["里程碑；重要事件"],"en":["an important event in the development of something"]}', NULL, 'reach/achieve a milestone / project milestone', '[{"en":"Reaching 1 million users was a major milestone.","zh-TW":"達到100萬用戶是一個重要的里程碑。"},{"en":"The project has several key milestones to meet.","zh-TW":"該項目有幾個關鍵里程碑需要完成。"}]', '{"noun":"milestone"}', NULL, 3, 1351),
(1352, 'milk', '/mɪlk/', 'noun', '{"zh-TW":["牛奶"],"en":["a white liquid from cows"]}', NULL, 'milk products / don''t cry over spilled milk', '[{"en":"The cafeteria offers various milk products.","zh-TW":"自助餐廳提供各種乳製品。"},{"en":"Don''t cry over spilled milk; move forward.","zh-TW":"不要為打翻的牛奶哭泣；向前看。"}]', '{"noun":"milk","adjective":"milky","verb":"milk"}', NULL, 1, 1352),
(1353, 'mind', '/maɪnd/', 'noun', '{"zh-TW":["心智；介意"],"en":["the thinking part of a person","to be bothered by"]}', NULL, 'keep in mind / never mind', '[{"en":"Keep in mind the budget limit.","zh-TW":"請記住預算限制。"},{"en":"Do you mind if I close the window?","zh-TW":"你介意我關窗戶嗎？"}]', '{"noun":"mind","verb":"mind","adjective":"mindful","noun2":"mindset"}', NULL, 1, 1353),
(1354, 'mineral', '/ˈmɪnərəl/', 'noun, adjective', '{"zh-TW":["礦物；礦產"],"en":["a natural substance found in the earth"]}', NULL, 'mineral resources/deposits/water', '[{"en":"The country is rich in mineral resources.","zh-TW":"該國礦產資源豐富。"},{"en":"Mineral water is available at the front desk.","zh-TW":"前台有提供礦泉水。"}]', '{"noun":"mineral, mining","adjective":"mineral"}', NULL, 3, 1354),
(1355, 'minimize', '/ˈmɪnɪmaɪz/', 'verb', '{"zh-TW":["最小化；減少"],"en":["to reduce to the smallest possible amount"]}', NULL, 'minimize risk/cost/damage', '[{"en":"We must minimize the risk of data loss.","zh-TW":"我們必須將數據丟失的風險降到最低。"},{"en":"The new procedure minimizes waste.","zh-TW":"新程序將浪費減到最少。"}]', '{"noun":"minimum","verb":"minimize","adjective":"minimum, minimal"}', NULL, 3, 1355),
(1356, 'ministry', '/ˈmɪnɪstri/', 'noun', '{"zh-TW":["部；部門（政府）"],"en":["a government department led by a minister"]}', NULL, 'Ministry of Finance/Education/Health', '[{"en":"The Ministry of Finance released the annual budget.","zh-TW":"財政部發布了年度預算。"},{"en":"She works at the Ministry of Education.","zh-TW":"她在教育部工作。"}]', '{"noun":"ministry, minister","adjective":"ministerial"}', NULL, 3, 1356),
(1357, 'minor', '/ˈmaɪnər/', 'adjective, noun', '{"zh-TW":["次要的；較小的","未成年人"],"en":["not very important; smaller","a person under the legal age"]}', NULL, 'minor issue/problem/change', '[{"en":"It''s only a minor issue and can be fixed quickly.","zh-TW":"這只是一個小問題，可以很快解決。"},{"en":"There were a few minor adjustments to the schedule.","zh-TW":"行程有一些小的調整。"}]', '{"noun":"minor, minority","adjective":"minor"}', NULL, 2, 1357),
(1358, 'minute', '/maɪˈnjuːt/', 'adjective', '{"zh-TW":["【主要意義-名詞】分鐘","【次要意義-形容詞】微小的；極細緻的；極詳盡的（重音在第二音節）","【次要意義-複數名詞】會議記錄（minutes）"],"en":["[primary - noun] a unit of time (60 seconds)","[secondary - adjective] extremely small or detailed (stress on second syllable: /maɪˈnjuːt/)","[secondary - plural noun] the official written record of a meeting"]}', NULL, 'minute details / minute examination / take the minutes / approve the minutes', '[{"en":"The inspector carried out a minute examination of the document.","zh-TW":"檢查員對該文件進行了極為詳細的審查。"},{"en":"Could you take the minutes at today''s board meeting?","zh-TW":"你能記錄今天董事會議的會議記錄嗎？"},{"en":"The difference between the two samples was minute but significant.","zh-TW":"兩個樣本之間的差異微乎其微但卻意義重大。"}]', '{"adverb":"minutely","noun":"minuteness"}', 'minute 作形容詞時重音移至第二音節，意為「微小的」；複數 minutes 意為「會議記錄」，兩者都是 TOEIC 高頻陷阱字。', 2, 1358),
(1359, 'misconduct', '/ˌmɪsˈkɑːndʌkt/', 'noun', '{"zh-TW":["不當行為；瀆職"],"en":["unacceptable or improper behavior, especially by a professional"]}', NULL, 'professional/employee misconduct / allegations of misconduct', '[{"en":"He was fired for gross misconduct.","zh-TW":"他因嚴重不當行為被解僱。"},{"en":"The investigation found evidence of financial misconduct.","zh-TW":"調查發現了財務不當行為的證據。"}]', '{"noun":"misconduct"}', NULL, 4, 1359),
(1360, 'mislead', '/ˌmɪsˈliːd/', 'verb', '{"zh-TW":["誤導；使產生錯誤印象"],"en":["to cause someone to have a wrong impression"]}', NULL, 'mislead consumers/investors / misleading information', '[{"en":"The advertisement was found to mislead consumers.","zh-TW":"該廣告被發現誤導消費者。"},{"en":"Don''t be misled by the low price.","zh-TW":"不要被低價格所誤導。"}]', '{"verb":"mislead","adjective":"misleading"}', NULL, 3, 1360),
(1361, 'miss', '/mɪs/', 'verb', '{"zh-TW":["錯過；想念"],"en":["to fail to attend or catch","to feel sad about absence"]}', NULL, 'miss the point / miss a deadline', '[{"en":"We cannot miss this opportunity.","zh-TW":"我們不能錯過這個機會。"},{"en":"Don''t miss the deadline.","zh-TW":"別錯過截止日期。"}]', '{"verb":"miss","adjective":"missing","noun":"miss"}', NULL, 1, 1361),
(1362, 'mistake', '/mɪˈsteɪk/', 'noun', '{"zh-TW":["錯誤"],"en":["something done incorrectly"]}', NULL, 'make a mistake / by mistake', '[{"en":"Everyone makes mistakes sometimes.","zh-TW":"每個人有時都會犯錯。"},{"en":"I sent the email by mistake.","zh-TW":"我不小心寄了那封郵件。"}]', '{"noun":"mistake","verb":"mistake","adjective":"mistaken"}', NULL, 3, 1362),
(1363, 'misunderstand', '/ˌmɪsʌndərˈstænd/', 'verb', '{"zh-TW":["誤解；誤會"],"en":["to fail to understand correctly"]}', NULL, 'misunderstand instructions/intentions', '[{"en":"I think you misunderstood my intentions.","zh-TW":"我想你誤解了我的意思。"},{"en":"The email was misunderstood by several recipients.","zh-TW":"這封電子郵件被幾位收件者誤解了。"}]', '{"noun":"misunderstanding","verb":"misunderstand"}', NULL, 5, 1363),
(1364, 'mitigate', '/ˈmɪtɪɡeɪt/', 'verb', '{"zh-TW":["減輕；緩和"],"en":["to make something less severe or harmful"]}', NULL, 'mitigate risk/damage/effects', '[{"en":"Steps were taken to mitigate the environmental impact.","zh-TW":"已採取措施減輕環境影響。"},{"en":"Insurance can help mitigate financial risk.","zh-TW":"保險可以幫助減輕財務風險。"}]', '{"noun":"mitigation","verb":"mitigate","adjective":"mitigating"}', NULL, 3, 1364),
(1365, 'mix', '/mɪks/', 'verb', '{"zh-TW":["混合"],"en":["to combine different things together"]}', NULL, 'product mix / mix up', '[{"en":"We need a better product mix.","zh-TW":"我們需要更好的產品組合。"},{"en":"There was a mix-up with the orders.","zh-TW":"訂單搞混了。"}]', '{"verb":"mix","noun":"mix","noun2":"mixture","noun3":"mix-up"}', NULL, 1, 1365),
(1366, 'mobile', '/ˈmoʊbl/', 'adjective, noun', '{"zh-TW":["移動的；手機的","行動電話"],"en":["able to move easily; relating to cell phones","a cell phone"]}', NULL, 'mobile device/app/phone / mobile banking', '[{"en":"Mobile banking has become increasingly popular.","zh-TW":"行動銀行越來越受歡迎。"},{"en":"More users access the site via mobile devices.","zh-TW":"越來越多用戶通過行動裝置訪問網站。"}]', '{"noun":"mobile, mobility","adjective":"mobile","verb":"mobilize"}', NULL, 2, 1366),
(1367, 'mobility', '/moʊˈbɪləti/', 'noun', '{"zh-TW":["流動性；移動性"],"en":["the ability to move freely; social advancement"]}', NULL, 'social/career mobility / labor mobility', '[{"en":"Career mobility is important to today''s workforce.","zh-TW":"職業流動性對當今勞動力很重要。"},{"en":"The new policy promotes upward social mobility.","zh-TW":"新政策促進了社會向上流動。"}]', '{"noun":"mobility, mobile","adjective":"mobile","verb":"mobilize"}', NULL, 3, 1367),
(1368, 'moderate', '/ˈmɑːdərət/', 'adjective, verb', '{"zh-TW":["適度的；中等的","調節；緩和"],"en":["average in amount; not extreme","to make less extreme"]}', NULL, 'moderate growth/risk/climate', '[{"en":"The company experienced moderate growth this year.","zh-TW":"公司今年經歷了適度的增長。"},{"en":"The chairman moderated the discussion.","zh-TW":"主席主持了討論。"}]', '{"noun":"moderation, moderator","adjective":"moderate","verb":"moderate","adverb":"moderately"}', NULL, 3, 1368),
(1369, 'modern', '/ˈmɒdərn/', 'adjective', '{"zh-TW":["現代的"],"en":["relating to the present time"]}', NULL, 'modern technology / modern design', '[{"en":"The office has a modern design.","zh-TW":"辦公室採用了現代設計。"},{"en":"Modern technology makes work easier.","zh-TW":"現代科技使工作更容易。"}]', '{"adjective":"modern","verb":"modernize","noun":"modernity","noun2":"modernization"}', NULL, 2, 1369),
(1370, 'modest', '/ˈmɒdɪst/', 'adjective', '{"zh-TW":["謙虛的；適度的"],"en":["unassuming in attitude","relatively moderate or small"]}', '{"root":{"text":"mod","meaning":"measure (適度)"},"suffix":{"text":"-est","meaning":"most (最)"},"logic":"保持適度的，即「謙虛的」。"}', 'modest income / modest improvement', '[{"en":"She is modest about her achievements.","zh-TW":"她對自己的成就很謙虛。"},{"en":"They live in a modest apartment.","zh-TW":"他們住在一間簡樸的公寓。"}]', '{"noun":"modesty","adverb":"modestly"}', NULL, 2, 1370),
(1371, 'modify', '/ˈmɒdɪfaɪ/', 'verb', '{"zh-TW":["修改；調整"],"en":["to make partial changes to something"]}', '{"root":{"text":"mod","meaning":"manner/measure (方式/適度)"},"suffix":{"text":"-ify","meaning":"make (使)"},"logic":"使其改變方式，即「修改」。"}', 'modify a plan / modify behavior / genetically modified; modify a plan/design/policy', '[{"en":"We need to modify the design slightly.","zh-TW":"我們需要稍微修改設計。"},{"en":"The software has been modified to fix the bug.","zh-TW":"軟體已被修改以修復錯誤。"},{"en":"We need to modify the proposal based on feedback.","zh-TW":"我們需要根據反饋修改提案。"},{"en":"The software was modified to fix the bug.","zh-TW":"軟體被修改以修復錯誤。"}]', '{"noun":"modification","adjective":"modified","verb":"modify"}', NULL, 2, 1371),
(1372, 'moisture', '/ˈmɔɪstʃər/', 'noun', '{"zh-TW":["水分；濕氣"],"en":["tiny drops of water in the air or on a surface"]}', '{"root":{"text":"moist","meaning":"wet (潮濕)"},"suffix":{"text":"-ure","meaning":"state (狀態)"},"logic":"潮濕的狀態，即「水分」。"}', 'moisture level / retain moisture', '[{"en":"The cream helps your skin retain moisture.","zh-TW":"這款乳霜幫助肌膚保持水分。"},{"en":"Excess moisture can cause mold growth.","zh-TW":"過多的濕氣會導致黴菌生長。"}]', '{"adjective":"moist","verb":"moisturize","noun":"moisturizer"}', NULL, 3, 1372),
(1373, 'moment', '/ˈmoʊmənt/', 'noun', '{"zh-TW":["片刻；時刻"],"en":["a very short period of time"]}', NULL, 'at the moment / for the moment', '[{"en":"I am busy at the moment.","zh-TW":"我目前很忙。"},{"en":"For the moment, let''s wait.","zh-TW":"暫時我們等一下。"}]', '{"noun":"moment","adjective":"momentary","adjective2":"momentous"}', NULL, 2, 1373),
(1374, 'momentum', '/moʊˈmentəm/', 'noun', '{"zh-TW":["動力；勢頭"],"en":["the force gained by movement; impetus"]}', NULL, 'gain/build/lose momentum', '[{"en":"The project is gaining momentum.","zh-TW":"該項目正在獲得動力。"},{"en":"We must not lose the momentum we have built.","zh-TW":"我們不能失去已經建立的勢頭。"}]', '{"noun":"momentum"}', NULL, 3, 1374),
(1375, 'monetary', '/ˈmɑːnɪteri/', 'adjective', '{"zh-TW":["貨幣的；金融的"],"en":["relating to money or currency"]}', NULL, 'monetary policy / monetary value / monetary system', '[{"en":"The central bank adjusted its monetary policy.","zh-TW":"央行調整了其貨幣政策。"},{"en":"The painting has both monetary and sentimental value.","zh-TW":"這幅畫既有金錢價值，也有情感價值。"}]', '{"noun":"money","adjective":"monetary"}', NULL, 3, 1375),
(1376, 'money', '/ˈmʌni/', 'noun', '{"zh-TW":["金錢"],"en":["coins and notes used to buy things"]}', NULL, 'make money / money management', '[{"en":"The company makes money from subscriptions.","zh-TW":"公司靠訂閱賺錢。"},{"en":"Good money management is essential.","zh-TW":"良好的資金管理至關重要。"}]', '{"noun":"money","adjective":"monetary"}', NULL, 2, 1376),
(1377, 'monitor', '/ˈmɒnɪtər/', 'verb', '{"zh-TW":["監控；監視","監控器；監視器","監控；監測"],"en":["to observe and check over a period of time","a screen or device for observing","to observe and check over time"]}', '{"root":{"text":"monit","meaning":"warn (警告)"},"suffix":{"text":"-or","meaning":"that which (…的東西)"},"logic":"提出警告的觀察，即「監控」。"}', 'monitor progress / monitor closely / heart monitor; monitor progress/performance/activity', '[{"en":"We will monitor the situation closely.","zh-TW":"我們將密切監控局勢。"},{"en":"The doctor monitors his blood pressure regularly.","zh-TW":"醫生定期監測他的血壓。"},{"en":"We use software to monitor network activity.","zh-TW":"我們使用軟體來監控網路活動。"},{"en":"The team monitors customer satisfaction closely.","zh-TW":"團隊密切監測客戶滿意度。"}]', '{"noun":"monitor","noun2":"monitoring","verb":"monitor"}', NULL, 3, 1377),
(1378, 'monopolize', '/məˈnɑːpəlaɪz/', 'verb', '{"zh-TW":["壟斷；獨占"],"en":["to have exclusive control over"]}', NULL, 'monopolize the market/conversation', '[{"en":"One company should not monopolize the entire market.","zh-TW":"一家公司不應壟斷整個市場。"},{"en":"He tends to monopolize every meeting.","zh-TW":"他傾向於在每次會議中獨占發言。"}]', '{"noun":"monopoly","verb":"monopolize","adjective":"monopolistic"}', NULL, 4, 1378),
(1379, 'monopoly', '/məˈnɑːpəli/', 'noun', '{"zh-TW":["壟斷；獨占"],"en":["exclusive control of a commodity or service"]}', NULL, 'have a monopoly on / break a monopoly', '[{"en":"The company has a virtual monopoly on the market.","zh-TW":"該公司幾乎壟斷了市場。"},{"en":"The government moved to break up the monopoly.","zh-TW":"政府採取行動打破壟斷。"}]', '{"noun":"monopoly","verb":"monopolize","adjective":"monopolistic"}', NULL, 3, 1379),
(1380, 'monsoon', '/mɒnˈsuːn/', 'noun', '{"zh-TW":["季風；雨季"],"en":["a seasonal wind bringing heavy rain"]}', '{"root":{"text":"mausim","meaning":"season (季節)"},"logic":"源自阿拉伯語 mausim（季節），指季節性風帶來的大雨。"}', 'monsoon season / monsoon rain', '[{"en":"The monsoon season brings heavy rainfall.","zh-TW":"雨季帶來大量降雨。"},{"en":"Flooding is common during the monsoon.","zh-TW":"雨季期間洪水很常見。"}]', '{"adjective":"monsoonal"}', NULL, 3, 1380),
